import { atlasesOf, effectNames, idleAtlasOf, portraitOf, urlsOf } from '../strip-urls';
import type { Atlas, FighterArt } from '../types';
import { RIFF_CELLS } from './cells';
import { RIFF_CLIPS } from './clips';
import { RIFF_SHEETS } from './sheets';

/** Strips generated by `npm run sprites` (tools/sprites), one folder per colorway. */
const MAIN = import.meta.glob<string>('./main/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT = import.meta.glob<string>('./alt/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** Front effects of the strips that have some (energy, flashes, sparks, dust). */
const MAIN_FX = import.meta.glob<string>('./main/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_FX = import.meta.glob<string>('./alt/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});

/**
 * The atlas written next to each image (tools/sprites/atlas.ts): where its frames are, cut to what
 * they draw and packed. The fight loads it with the image.
 */
const MAIN_ATLASES = import.meta.glob<string>('./main/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_ATLASES = import.meta.glob<string>('./alt/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** The idle's atlases, bundled: the select screen shows its frames at once. */
const IDLE_ATLASES = import.meta.glob<Atlas>('./*/idle.json', { eager: true, import: 'default' });

const SHARED = {
  // Her crest and her raised fist, on the character select screen.
  portrait: { x: 28, y: 4, size: 58 },
  sheets: RIFF_SHEETS,
  clips: RIFF_CLIPS,
  cells: RIFF_CELLS,
};

/** The punk: black leather, magenta fringe and energy, silver studs. */
export const RIFF: FighterArt = {
  key: 'riff',
  urls: urlsOf(MAIN, 'main', RIFF_SHEETS),
  fx: urlsOf(MAIN_FX, 'main/fx', effectNames(RIFF_SHEETS, RIFF_CLIPS)),
  atlases: atlasesOf(MAIN_ATLASES, 'main', RIFF_SHEETS, effectNames(RIFF_SHEETS, RIFF_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'main', RIFF_CLIPS.idle.sheet),
  ...portraitOf(MAIN, 'main'),
  ...SHARED,
};
/** The red leather jacket, the gold fringe and energy: player 2 in a mirror match. */
export const RIFF_ALT: FighterArt = {
  key: 'riff-alt',
  urls: urlsOf(ALT, 'alt', RIFF_SHEETS),
  fx: urlsOf(ALT_FX, 'alt/fx', effectNames(RIFF_SHEETS, RIFF_CLIPS)),
  atlases: atlasesOf(ALT_ATLASES, 'alt', RIFF_SHEETS, effectNames(RIFF_SHEETS, RIFF_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'alt', RIFF_CLIPS.idle.sheet),
  ...portraitOf(ALT, 'alt'),
  ...SHARED,
};
